"""Top samples by dose."""


def _take_largest(samples):
    """Remove and return the sample with the largest dose."""
    best = max(samples, key=lambda x: x.dose)
    samples.remove(best)
    return best


def podium(samples, places=3):
    """Return the top `places` samples by dose, largest first. The caller's list is left as it was."""
    top = []
    while samples and len(top) < places:
        top.append(_take_largest(samples))
    return top


def report(samples):
    """Return the podium values, the number of samples and every dose."""
    return {"podium": [x.dose for x in podium(samples)], "count": len(samples), "all": [x.dose for x in samples]}


def batch_names(samples):
    """Return the distinct batch values, in first-seen order."""
    names = []
    for x in samples:
        if x.batch not in names:
            names.append(x.batch)
    return names


def group_by_batch(samples):
    """Return a dict from batch to the list of samples with that batch."""
    groups = {}
    for x in samples:
        groups.setdefault(x.batch, []).append(x)
    return groups

