from samples import load_samples, ROWS
from leaders import podium, report

VALUES = [v for _, v in ROWS]


def test_count():
    assert report(list(load_samples()))["count"] == len(ROWS)


def test_all_values_kept():
    assert report(list(load_samples()))["all"] == VALUES


def test_podium_values():
    top = podium(list(load_samples()))
    assert [x.dose for x in top] == sorted(VALUES, reverse=True)[:3]


def test_caller_list_unchanged():
    data = list(load_samples())
    podium(data, 2)
    assert [x.dose for x in data] == VALUES


def test_one_place():
    assert [x.dose for x in podium(list(load_samples()), 1)] == [max(VALUES)]
